package delivery
import("encoding/json";"errors";"net/http";"strings";"backend/internal/contract/repository";"backend/internal/contract/usecase";"backend/internal/pkg/httpx";"backend/internal/pkg/response")
type ContractController struct{uc *usecase.ContractUsecase}
func NewContractController(u *usecase.ContractUsecase)*ContractController{return &ContractController{uc:u}}
type listRequest struct{CurrentPage int `json:"current_page"`;PerPage int `json:"per_page"`;Keyword string `json:"keyword"`;Status string `json:"status"`}
func(c *ContractController)List(w http.ResponseWriter,r *http.Request){var q listRequest;if json.NewDecoder(r.Body).Decode(&q)!=nil{response.WriteError(w,400,"INVALID_INPUT","invalid request body");return};p,n:=httpx.NormalizePagination(q.CurrentPage,q.PerPage);s:=strings.TrimSpace(q.Status);if s!=""&&!validStatus(s){response.WriteError(w,400,"INVALID_INPUT","invalid status");return};rows,total,e:=c.uc.List(repository.ContractFilter{Keyword:strings.TrimSpace(q.Keyword),Status:s},p,n);if e!=nil{response.WriteError(w,500,"INTERNAL_ERROR","failed to list contracts");return};response.WriteSuccess(w,200,response.NewListData(rows,p,n,total))}
func(c *ContractController)Detail(w http.ResponseWriter,r *http.Request){id,e:=httpx.ParseIDParam(r);if e!=nil{response.WriteError(w,400,"INVALID_INPUT","invalid id");return};row,e:=c.uc.Detail(id);if e!=nil{if errors.Is(e,repository.ErrNotFound){response.WriteError(w,404,"NOT_FOUND","contract not found")}else{response.WriteError(w,500,"INTERNAL_ERROR","failed to load contract")};return};response.WriteSuccess(w,200,row)}
type saveRequest struct{TenantID uint `json:"tenant_id"`;StartDate string `json:"start_date"`;EndDate string `json:"end_date"`;MonthlyRent float64 `json:"monthly_rent"`;SecurityDeposit float64 `json:"security_deposit"`;BillingDay int `json:"billing_day"`;Status string `json:"status"`;Notes string `json:"notes"`}
func(c *ContractController)Create(w http.ResponseWriter,r *http.Request){c.save(w,r,0)}
func(c *ContractController)Update(w http.ResponseWriter,r *http.Request){id,e:=httpx.ParseIDParam(r);if e!=nil{response.WriteError(w,400,"INVALID_INPUT","invalid id");return};c.save(w,r,id)}
func(c *ContractController)save(w http.ResponseWriter,r *http.Request,id uint){var q saveRequest;if json.NewDecoder(r.Body).Decode(&q)!=nil{response.WriteError(w,400,"INVALID_INPUT","invalid request body");return};s:=strings.TrimSpace(q.Status);if s==""{s="draft"};d:=q.BillingDay;if d==0{d=1};cdata:=&repository.Contract{ID:id,TenantID:q.TenantID,StartDate:strings.TrimSpace(q.StartDate),EndDate:strings.TrimSpace(q.EndDate),MonthlyRent:q.MonthlyRent,SecurityDeposit:q.SecurityDeposit,BillingDay:d,Status:s,Notes:strings.TrimSpace(q.Notes)}
 if e:=c.uc.Save(cdata);e!=nil{switch{case errors.Is(e,repository.ErrTenantNotFound):response.WriteError(w,400,"TENANT_NOT_FOUND","tenant not found");case errors.Is(e,repository.ErrActiveContractExists):response.WriteError(w,409,"ACTIVE_CONTRACT_EXISTS","tenant already has an active contract");case errors.Is(e,repository.ErrInvalidContract):response.WriteError(w,400,"INVALID_CONTRACT","check tenant, dates, amounts, billing day and status");case errors.Is(e,repository.ErrNotFound):response.WriteError(w,404,"NOT_FOUND","contract not found");default:response.WriteError(w,500,"INTERNAL_ERROR","failed to save contract")};return};code:=http.StatusOK;if id==0{code=http.StatusCreated};response.WriteSuccess(w,code,cdata)}
func validStatus(s string)bool{return s=="draft"||s=="active"||s=="expired"||s=="terminated"}
